def can_reconstruct_words(N, lengths):
    from collections import deque

    # Initialize the trie
    trie = {}

    # Function to insert a word into the trie
    def insert_word(word):
        node = trie
        for char in word:
            if char not in node:
                node[char] = {}
            node = node[char]

    # Function to check if a word can be inserted without being a prefix
    def can_insert_word(word):
        node = trie
        for char in word:
            if char not in node:
                node[char] = {}
            node = node.get(char)
            if not node:
                return True
        return False

    # Try to construct the words
    words = []
    for length in lengths:
        found = False
        for i in range(2 ** length):
            word = bin(i)[2:].zfill(length)
            if can_insert_word(word):
                insert_word(word)
                words.append(word)
                found = True
                break
        if not found:
            return "NO"

